import {
  Group,
  PlaneGeometry,
  MeshBasicNodeMaterial,
  Mesh,
  Vector3,
} from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  // Extract scene placement
  const pos = config.scenePosition || new Vector3(0, -2.85, 0.26);
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale || { x: 1, y: 1, z: 1 };
  group.position.copy(pos);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  // Load brushed metal texture
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  texture.wrapS = texture.wrapT = 1001; // RepeatWrapping
  texture.anisotropy = 16;

  // Create background plane (sized dynamically after text creation)
  const pad = 0.15; // padding around text in scene units
  let planeMesh = null;
  let textMesh = null;

  // Process text content
  if (config.textContent && config.textContent.length > 0) {
    const textItem = config.textContent[0];
    const { text } = textItem;
    // Map font size from token (headline -> 0.34)
    const fontSize = 0.34; // scene units
    const fontFamily = 'Lora';
    const fontWeight = 400;
    const color = '#ff2a38'; // accent

    // Create text mesh via font atlas
    textMesh = ctx.fontAtlas.createText({
      text,
      fontFamily,
      fontWeight,
      fontSize,
      color,
    });

    // Get text bounding box to size background
    textMesh.geometry.computeBoundingBox();
    const box = textMesh.geometry.boundingBox;
    const textWidth = box.max.x - box.min.x;
    const textHeight = box.max.y - box.min.y;

    // Size background plane
    const planeWidth = textWidth + pad * 2;
    const planeHeight = textHeight + pad * 2;
    const planeGeo = new PlaneGeometry(planeWidth, planeHeight);
    const planeMat = new MeshBasicNodeMaterial({
      map: texture,
      side: 2, // DoubleSide
    });
    planeMesh = new Mesh(planeGeo, planeMat);

    // Center text relative to plane
    const centerX = box.min.x + textWidth / 2;
    const centerY = box.min.y + textHeight / 2;
    textMesh.position.set(-centerX, -centerY, 0.001); // slight z push to avoid z-fighting

    group.add(planeMesh);
    group.add(textMesh);
  }

  // Attach handlers (none in this node)
  group.userData.handlers = {};

  // Cleanup function
  group.userData.cleanup = () => {
    if (planeMesh) {
      planeMesh.geometry.dispose();
      planeMesh.material.dispose();
    }
    if (textMesh) {
      // Assume font atlas text has its own cleanup method or we dispose geometry
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }
    texture.dispose();
  };

  return group;
}
